{
  "name": "chrome-devtools-testing",
  "version": "1.0.0",
  "type": "module",
  "scripts": {
    "start-server": "bun x tsx scripts/start-server.ts",
    "dev": "bun x tsx --watch src/server.ts"
  },
  "dependencies": {
    "express": "^4.21.0",
    "playwright": "^1.49.0"
  },
  "devDependencies": {
    "@types/express": "^5.0.0",
    "tsx": "^4.21.0"
  }
}

declare global {
  interface Window {
    __devBrowserRefs: Record<string, Element>;
  }
}

interface AriaNode {
  role: string;
  name: string;
  checked?: boolean | "mixed";
  disabled?: boolean;
  expanded?: boolean;
  level?: number;
  pressed?: boolean | "mixed";
  selected?: boolean;
  children?: (AriaNode | string)[];
  ref?: string;
  url?: string;
  placeholder?: string;
}

interface AriaSnapshot {
  root: AriaNode;
  elements: Map<string, Element>;
  refs: Map<Element, string>;
}

let refCounter = 0;

function isVisible(element: Element): boolean {
  const style = window.getComputedStyle(element);
  if (style.display === "none" || style.visibility === "hidden") return false;
  if (parseFloat(style.opacity) === 0) return false;

  const rect = element.getBoundingClientRect();
  if (rect.width === 0 && rect.height === 0) return false;

  return true;
}

function isInteractable(element: Element): boolean {
  const interactiveRoles = [
    "button",
    "link",
    "textbox",
    "checkbox",
    "radio",
    "combobox",
    "listbox",
    "option",
    "menuitem",
    "tab",
    "switch",
    "slider",
    "spinbutton",
    "searchbox",
  ];

  const tagName = element.tagName.toLowerCase();
  const interactiveTags = ["a", "button", "input", "select", "textarea"];

  if (interactiveTags.includes(tagName)) return true;

  const role = element.getAttribute("role");
  if (role && interactiveRoles.includes(role)) return true;

  if (element.hasAttribute("onclick") || element.hasAttribute("tabindex"))
    return true;

  return false;
}

function getAriaRole(element: Element): string {
  const explicitRole = element.getAttribute("role");
  if (explicitRole) return explicitRole;

  const tagName = element.tagName.toLowerCase();
  const roleMap: Record<string, string> = {
    a: "link",
    button: "button",
    input: getInputRole(element as HTMLInputElement),
    select: "combobox",
    textarea: "textbox",
    img: "img",
    nav: "navigation",
    main: "main",
    header: "banner",
    footer: "contentinfo",
    aside: "complementary",
    article: "article",
    section: "region",
    form: "form",
    table: "table",
    ul: "list",
    ol: "list",
    li: "listitem",
    h1: "heading",
    h2: "heading",
    h3: "heading",
    h4: "heading",
    h5: "heading",
    h6: "heading",
  };

  return roleMap[tagName] || "generic";
}

function getInputRole(input: HTMLInputElement): string {
  const type = input.type.toLowerCase();
  const typeRoleMap: Record<string, string> = {
    text: "textbox",
    password: "textbox",
    email: "textbox",
    tel: "textbox",
    url: "textbox",
    search: "searchbox",
    checkbox: "checkbox",
    radio: "radio",
    button: "button",
    submit: "button",
    reset: "button",
    range: "slider",
    number: "spinbutton",
  };
  return typeRoleMap[type] || "textbox";
}

function getAccessibleName(element: Element): string {
  const ariaLabel = element.getAttribute("aria-label");
  if (ariaLabel) return ariaLabel;

  const ariaLabelledBy = element.getAttribute("aria-labelledby");
  if (ariaLabelledBy) {
    const labels = ariaLabelledBy
      .split(" ")
      .map((id) => document.getElementById(id)?.textContent?.trim())
      .filter(Boolean);
    if (labels.length) return labels.join(" ");
  }

  const tagName = element.tagName.toLowerCase();

  if (tagName === "input" || tagName === "textarea" || tagName === "select") {
    const id = element.getAttribute("id");
    if (id) {
      const label = document.querySelector(`label[for="${id}"]`);
      if (label) return label.textContent?.trim() || "";
    }
  }

  if (tagName === "img") {
    return (element as HTMLImageElement).alt || "";
  }

  if (tagName === "a" || tagName === "button") {
    return element.textContent?.trim() || "";
  }

  return "";
}

function toAriaNode(element: Element, snapshot: AriaSnapshot): AriaNode | null {
  if (!isVisible(element)) return null;

  const role = getAriaRole(element);
  if (role === "generic" && !isInteractable(element)) return null;

  const name = getAccessibleName(element);
  const node: AriaNode = { role, name };

  if (element.getAttribute("aria-checked"))
    node.checked = element.getAttribute("aria-checked") === "true";
  if ((element as HTMLInputElement).checked !== undefined) {
    const input = element as HTMLInputElement;
    if (input.type === "checkbox" || input.type === "radio")
      node.checked = input.checked;
  }

  if (element.hasAttribute("disabled") || element.getAttribute("aria-disabled") === "true")
    node.disabled = true;

  if (element.getAttribute("aria-expanded"))
    node.expanded = element.getAttribute("aria-expanded") === "true";

  if (element.getAttribute("aria-pressed"))
    node.pressed = element.getAttribute("aria-pressed") === "true";

  if (element.getAttribute("aria-selected"))
    node.selected = element.getAttribute("aria-selected") === "true";

  const tagName = element.tagName.toLowerCase();
  if (tagName.match(/^h[1-6]$/)) {
    node.level = parseInt(tagName[1]);
  }

  if (tagName === "a") {
    const href = (element as HTMLAnchorElement).href;
    if (href && !href.startsWith("javascript:")) {
      node.url = href;
    }
  }

  if ((element as HTMLInputElement).placeholder) {
    node.placeholder = (element as HTMLInputElement).placeholder;
  }

  if (isInteractable(element) && isVisible(element)) {
    const ref = `e${++refCounter}`;
    node.ref = ref;
    snapshot.elements.set(ref, element);
    snapshot.refs.set(element, ref);
  }

  return node;
}

function visitNode(
  node: Node,
  snapshot: AriaSnapshot,
  parent: AriaNode
): void {
  if (node.nodeType === Node.TEXT_NODE) {
    const text = node.textContent?.trim();
    if (text) {
      if (!parent.children) parent.children = [];
      parent.children.push(text);
    }
    return;
  }

  if (node.nodeType !== Node.ELEMENT_NODE) return;

  const element = node as Element;
  const ariaNode = toAriaNode(element, snapshot);

  if (ariaNode) {
    if (!parent.children) parent.children = [];
    parent.children.push(ariaNode);

    for (const child of element.childNodes) {
      visitNode(child, snapshot, ariaNode);
    }
  } else {
    for (const child of element.childNodes) {
      visitNode(child, snapshot, parent);
    }
  }
}

function generateAriaTree(root: Element): AriaSnapshot {
  refCounter = 0;
  const snapshot: AriaSnapshot = {
    root: { role: "document", name: document.title, children: [] },
    elements: new Map(),
    refs: new Map(),
  };

  for (const child of root.childNodes) {
    visitNode(child, snapshot, snapshot.root);
  }

  return snapshot;
}

function escapeYamlString(str: string): string {
  if (!str) return '""';
  if (/[\n\r\t:{}[\]&*#?|<>=!%@\x60]/.test(str) || str.includes('"')) {
    return '"' + str.replace(/"/g, '\\"').replace(/\n/g, "\\n") + '"';
  }
  return '"' + str + '"';
}

function renderAriaNode(node: AriaNode | string, indent: number): string {
  const prefix = "  ".repeat(indent);

  if (typeof node === "string") {
    return `${prefix}- text: ${escapeYamlString(node)}\n`;
  }

  let line = `${prefix}- ${node.role}`;

  if (node.name) {
    line += ` ${escapeYamlString(node.name)}`;
  }

  const attrs: string[] = [];
  if (node.ref) attrs.push(`ref=${node.ref}`);
  if (node.checked !== undefined)
    attrs.push(node.checked ? "checked" : "unchecked");
  if (node.disabled) attrs.push("disabled");
  if (node.expanded !== undefined)
    attrs.push(node.expanded ? "expanded" : "collapsed");
  if (node.pressed !== undefined) attrs.push(node.pressed ? "pressed" : "");
  if (node.selected) attrs.push("selected");
  if (node.level) attrs.push(`level=${node.level}`);

  if (attrs.length) {
    line += ` [${attrs.filter(Boolean).join(", ")}]`;
  }

  if (node.url) {
    line += `\n${prefix}  /url: ${node.url}`;
  }
  if (node.placeholder) {
    line += `\n${prefix}  /placeholder: ${escapeYamlString(node.placeholder)}`;
  }

  let result = line + "\n";

  if (node.children && node.children.length) {
    for (const child of node.children) {
      result += renderAriaNode(child, indent + 1);
    }
  }

  return result;
}

function renderAriaTree(snapshot: AriaSnapshot): string {
  let yaml = "";
  if (snapshot.root.children) {
    for (const child of snapshot.root.children) {
      yaml += renderAriaNode(child, 0);
    }
  }
  return yaml;
}

export function getAISnapshot(): string {
  const snapshot = generateAriaTree(document.body);
  const refsObject: Record<string, Element> = {};
  for (const [ref, element] of snapshot.elements) {
    refsObject[ref] = element;
  }
  window.__devBrowserRefs = refsObject;
  return renderAriaTree(snapshot);
}

export function getRefElement(ref: string): Element | null {
  return window.__devBrowserRefs?.[ref] || null;
}

# Chrome DevTools Testing

A Playwright-based browser testing skill for Claude Code that connects directly to Chrome via CDP. Supports batch scripting (multiple actions per turn), auto-wait, ARIA snapshots, and full DevTools debugging.

Inspired by [SawyerHood/dev-browser](https://github.com/SawyerHood/dev-browser).

## Features

- **Batch Scripting**: Execute multiple browser actions in a single heredoc script
- **Persistent Pages**: Browser pages survive client disconnections
- **Smart Page Load Detection**: Filters ads/tracking, handles stuck requests gracefully
- **ARIA Snapshots**: Accessibility tree with refs for element targeting
- **Playwright Locators**: Robust element selection with auto-wait
- **DevTools Debugging**: Console capture, network monitoring, performance tracing

## Installation

```bash
cd ~/.claude/skills/chrome-devtools-testing
bun install
```

## Usage

### 1. Start the Server

```bash
bun run start-server
```

Options:
- `--headless` - Run browser without UI
- `--port=9333` - Use custom port (default: 9222)

### 2. Run Scripts

```bash
bun x tsx <<'EOF'
import { connect } from "./src/client.js";

const client = await connect();
const page = await client.page("main");

await page.goto("http://localhost:3000");
await page.fill('[name="email"]', "test@example.com");
await page.click('button[type="submit"]');
await page.screenshot({ path: "/tmp/result.png" });

await client.disconnect();
EOF
```

## API Reference

### Client

```typescript
import { connect } from "./src/client.js";

const client = await connect("http://localhost:9222");

// Page management
const page = await client.page("main");      // Get or create named page
const pages = await client.listPages();       // List all pages
await client.closePage("main");               // Close a page
await client.disconnect();                    // Disconnect (pages persist)

// ARIA snapshots
const snapshot = await client.getAISnapshot("main");
const element = await client.selectSnapshotRef("main", "e5");
```

### Page (Playwright)

```typescript
// Navigation
await page.goto("https://example.com");
await page.goBack();
await page.reload();

// Locators (recommended)
await page.getByRole("button", { name: "Submit" }).click();
await page.getByLabel("Email").fill("test@example.com");
await page.getByText("Welcome").waitFor();

// CSS selectors
await page.locator(".submit-btn").click();
await page.locator("#email").fill("test@example.com");

// Screenshots
await page.screenshot({ path: "/tmp/page.png" });
await page.screenshot({ path: "/tmp/full.png", fullPage: true });
```

### Wait for Page Load

```typescript
import { waitForPageLoad } from "./src/client.js";

const result = await waitForPageLoad(page, {
  timeout: 10000,           // Max wait (default: 10s)
  pollInterval: 50,         // Check frequency (default: 50ms)
  minimumWait: 100,         // Initial wait (default: 100ms)
  waitForNetworkIdle: true  // Wait for no pending requests
});

// Result: { success, readyState, pendingRequests, waitTimeMs, timedOut }
```

Smart filtering ignores:
- Ad/tracking domains (Google Analytics, Facebook, Hotjar, etc.)
- Non-critical resources after 3s (images, fonts)
- Stuck requests (>10s)

### Debugging

```typescript
// Console messages
const logs = await client.getConsoleMessages(page, {
  types: ["error", "warn"],
  limit: 50
});

// Network requests
const requests = await client.getNetworkRequests(page, {
  types: ["xhr", "fetch"]
});

// Performance metrics
const metrics = await client.getPerformanceMetrics(page);
// { lcp, fcp, cls, ttfb, domContentLoaded, load }

// Core Web Vitals
const vitals = await client.getCoreWebVitals(page);
// { lcp, fid, cls, ttfb }

// Performance tracing
await client.startPerformanceTrace(page);
await page.reload();
const trace = await client.stopPerformanceTrace(page);
```

### ARIA Snapshots

```typescript
const snapshot = await client.getAISnapshot("main");
console.log(snapshot);
```

Output:
```yaml
- navigation:
  - link "Home" [ref=e1]
  - link "Products" [ref=e2]
- main:
  - heading "Welcome" [level=1]
  - form:
    - textbox "Email" [ref=e5]
    - button "Submit" [ref=e6]
```

Interact via refs:
```typescript
const button = await client.selectSnapshotRef("main", "e6");
await button?.click();
```

## Examples

### Form Submission

```typescript
import { connect, waitForPageLoad } from "./src/client.js";

const client = await connect();
const page = await client.page("main");

await page.goto("http://localhost:3000/login");
await waitForPageLoad(page);

await page.getByLabel("Email").fill("user@example.com");
await page.getByLabel("Password").fill("secret123");
await page.getByRole("button", { name: "Sign In" }).click();

await page.getByText("Welcome").waitFor();
await page.screenshot({ path: "/tmp/logged-in.png" });

await client.disconnect();
```

### Debug Page Issues

```typescript
import { connect } from "./src/client.js";

const client = await connect();
const page = await client.page("debug");

await page.goto("http://localhost:3000");

const errors = await client.getConsoleMessages(page, { types: ["error"] });
console.log("Errors:", errors);

const requests = await client.getNetworkRequests(page, { types: ["xhr", "fetch"] });
console.log("API calls:", requests);

const vitals = await client.getCoreWebVitals(page);
console.log("Web Vitals:", vitals);

await client.disconnect();
```

## Architecture

```
├── src/
│   ├── client.ts      # Client: connect, page management, waitForPageLoad
│   ├── server.ts      # Server: persistent browser, REST API
│   ├── devtools.ts    # CDP debugging: console, network, performance
│   ├── types.ts       # Shared TypeScript types
│   └── snapshot/
│       ├── browser-script.ts  # ARIA tree extraction (browser-injected)
│       └── index.ts           # Snapshot injection wrapper
├── scripts/
│   └── start-server.ts        # Server entry point
├── package.json
├── tsconfig.json
└── SKILL.md                   # Claude Code skill documentation
```

