import type { Page, CDPSession } from "playwright";
import type { ConsoleMessage, NetworkRequest, PerformanceMetrics } from "./types.js";

interface TracingState {
  session: CDPSession;
  traceEvents: unknown[];
}

const tracingStates = new Map<Page, TracingState>();

export async function getConsoleMessages(
  page: Page,
  options: { types?: string[]; limit?: number } = {}
): Promise<ConsoleMessage[]> {
  const { types, limit = 100 } = options;

  const consoleMessages = await page.evaluate(() => {
    return (window as unknown as { __consoleMessages?: ConsoleMessage[] }).__consoleMessages || [];
  });

  let filtered = consoleMessages;
  if (types && types.length) {
    filtered = filtered.filter((m) => types.includes(m.type));
  }

  return filtered.slice(-limit);
}

export async function setupConsoleCapture(page: Page): Promise<void> {
  await page.evaluate(() => {
    if ((window as unknown as { __consoleMessages?: ConsoleMessage[] }).__consoleMessages) return;

    (window as unknown as { __consoleMessages: ConsoleMessage[] }).__consoleMessages = [];
    const originalConsole = { ...console };

    const capture = (type: string) => (...args: unknown[]) => {
      (window as unknown as { __consoleMessages: ConsoleMessage[] }).__consoleMessages.push({
        type,
        text: args.map((a) => (typeof a === "object" ? JSON.stringify(a) : String(a))).join(" "),
        timestamp: Date.now(),
      });
      (originalConsole as unknown as Record<string, (...args: unknown[]) => void>)[type]?.(...args);
    };

    console.log = capture("log");
    console.warn = capture("warn");
    console.error = capture("error");
    console.info = capture("info");
    console.debug = capture("debug");
  });

  page.on("console", (msg) => {
    page.evaluate(
      ({ type, text }) => {
        (window as unknown as { __consoleMessages: ConsoleMessage[] }).__consoleMessages?.push({
          type,
          text,
          timestamp: Date.now(),
        });
      },
      { type: msg.type(), text: msg.text() }
    );
  });
}

export async function getNetworkRequests(
  page: Page,
  options: { types?: string[]; limit?: number } = {}
): Promise<NetworkRequest[]> {
  const { types, limit = 100 } = options;

  const requests = await page.evaluate(() => {
    return (window as unknown as { __networkRequests?: NetworkRequest[] }).__networkRequests || [];
  });

  let filtered = requests;
  if (types && types.length) {
    filtered = filtered.filter((r) => types.includes(r.type));
  }

  return filtered.slice(-limit);
}

export async function setupNetworkCapture(page: Page): Promise<void> {
  await page.evaluate(() => {
    if ((window as unknown as { __networkRequests?: NetworkRequest[] }).__networkRequests) return;
    (window as unknown as { __networkRequests: NetworkRequest[] }).__networkRequests = [];
  });

  page.on("request", (request) => {
    page.evaluate(
      (req) => {
        (window as unknown as { __networkRequests: NetworkRequest[] }).__networkRequests?.push(req);
      },
      {
        id: request.url(),
        url: request.url(),
        method: request.method(),
        type: request.resourceType(),
        timing: { startTime: Date.now() },
      } as NetworkRequest
    );
  });

  page.on("response", async (response) => {
    const url = response.url();
    const status = response.status();

    await page.evaluate(
      ({ url, status }) => {
        const requests = (window as unknown as { __networkRequests: NetworkRequest[] }).__networkRequests;
        const req = requests?.find((r) => r.url === url && !r.status);
        if (req) {
          req.status = status;
          if (req.timing) {
            req.timing.endTime = Date.now();
            req.timing.duration = req.timing.endTime - req.timing.startTime;
          }
        }
      },
      { url, status }
    );
  });
}

export async function startPerformanceTrace(page: Page): Promise<void> {
  const context = page.context();
  const session = await context.newCDPSession(page);

  await session.send("Performance.enable");
  await session.send("Tracing.start", {
    categories: [
      "devtools.timeline",
      "blink.user_timing",
      "loading",
      "devtools.timeline.frame",
    ].join(","),
    options: "sampling-frequency=10000",
  });

  tracingStates.set(page, { session, traceEvents: [] });
}

export async function stopPerformanceTrace(page: Page): Promise<unknown[]> {
  const state = tracingStates.get(page);
  if (!state) throw new Error("No active trace for this page");

  const events: unknown[] = [];

  return new Promise((resolve, reject) => {
    state.session.on("Tracing.dataCollected", (data) => {
      events.push(...(data.value as unknown[]));
    });

    state.session.on("Tracing.tracingComplete", () => {
      tracingStates.delete(page);
      resolve(events);
    });

    state.session.send("Tracing.end").catch(reject);
  });
}

export async function getPerformanceMetrics(page: Page): Promise<PerformanceMetrics> {
  const metrics = await page.evaluate(() => {
    const perf = performance;
    const navigation = perf.getEntriesByType("navigation")[0] as PerformanceNavigationTiming;
    const paint = perf.getEntriesByType("paint");
    const lcp = perf.getEntriesByType("largest-contentful-paint");

    const fcp = paint.find((p) => p.name === "first-contentful-paint");
    const lcpEntry = lcp[lcp.length - 1];

    let cls = 0;
    const layoutShifts = perf.getEntriesByType("layout-shift") as (PerformanceEntry & { value: number; hadRecentInput: boolean })[];
    for (const entry of layoutShifts) {
      if (!entry.hadRecentInput) {
        cls += entry.value;
      }
    }

    return {
      fcp: fcp?.startTime,
      lcp: (lcpEntry as PerformanceEntry & { startTime: number })?.startTime,
      cls,
      ttfb: navigation?.responseStart - navigation?.requestStart,
      domContentLoaded: navigation?.domContentLoadedEventEnd,
      load: navigation?.loadEventEnd,
    };
  });

  return metrics;
}

export async function getCoreWebVitals(page: Page): Promise<{
  lcp: number | null;
  fid: number | null;
  cls: number | null;
  ttfb: number | null;
}> {
  return page.evaluate(() => {
    return new Promise((resolve) => {
      const vitals = {
        lcp: null as number | null,
        fid: null as number | null,
        cls: null as number | null,
        ttfb: null as number | null,
      };

      const navigation = performance.getEntriesByType("navigation")[0] as PerformanceNavigationTiming;
      if (navigation) {
        vitals.ttfb = navigation.responseStart - navigation.requestStart;
      }

      const lcpEntries = performance.getEntriesByType("largest-contentful-paint");
      if (lcpEntries.length) {
        vitals.lcp = (lcpEntries[lcpEntries.length - 1] as PerformanceEntry & { startTime: number }).startTime;
      }

      let clsValue = 0;
      const layoutShifts = performance.getEntriesByType("layout-shift") as (PerformanceEntry & { value: number; hadRecentInput: boolean })[];
      for (const entry of layoutShifts) {
        if (!entry.hadRecentInput) {
          clsValue += entry.value;
        }
      }
      vitals.cls = clsValue;

      const fidEntries = performance.getEntriesByType("first-input") as (PerformanceEntry & { processingStart: number; startTime: number })[];
      if (fidEntries.length) {
        vitals.fid = fidEntries[0].processingStart - fidEntries[0].startTime;
      }

      resolve(vitals);
    });
  });
}

import { serve } from "../src/server.js";

const headless = process.argv.includes("--headless");
const portArg = process.argv.find((a) => a.startsWith("--port="));
const port = portArg ? parseInt(portArg.split("=")[1]) : 9222;

console.log("Starting Chrome DevTools Testing server...");
console.log(`  Port: ${port}`);
console.log(`  Headless: ${headless}`);

serve({ port, headless }).then((server) => {
  console.log(`Server ready at http://localhost:${server.port}`);
  console.log(`WebSocket endpoint: ${server.wsEndpoint}`);
