import express from "express";
import { chromium, type BrowserContext, type Page } from "playwright";
import { mkdirSync, existsSync } from "fs";
import { join } from "path";
import { homedir } from "os";
import type {
  ServerOptions,
  GetPageResponse,
  ListPagesResponse,
  ServerInfoResponse,
  DevBrowserServer,
} from "./types.js";

async function fetchWithRetry(
  url: string,
  options: { retries?: number; delay?: number } = {}
): Promise<Response> {
  const { retries = 5, delay = 500 } = options;

  for (let i = 0; i < retries; i++) {
    try {
      const response = await fetch(url);
      if (response.ok) return response;
    } catch {
      if (i === retries - 1) throw new Error(`Failed to fetch ${url}`);
    }
    await new Promise((r) => setTimeout(r, delay * Math.pow(2, i)));
  }
  throw new Error(`Failed to fetch ${url}`);
}

export async function serve(options: ServerOptions = {}): Promise<DevBrowserServer> {
  const {
    port = 9222,
    headless = false,
    cdpPort = 9223,
    profileDir,
  } = options;

  if (port === cdpPort) {
    throw new Error("API port and CDP port must be different");
  }

  const userDataDir =
    profileDir || join(homedir(), ".chrome-devtools-testing", "profile");

  if (!existsSync(userDataDir)) {
    mkdirSync(userDataDir, { recursive: true });
  }

  console.log(`Launching browser with profile: ${userDataDir}`);

  const context: BrowserContext = await chromium.launchPersistentContext(
    userDataDir,
    {
      headless,
      args: [`--remote-debugging-port=${cdpPort}`],
    }
  );

  const cdpUrl = `http://127.0.0.1:${cdpPort}/json/version`;
  const versionResponse = await fetchWithRetry(cdpUrl);
  const versionInfo = (await versionResponse.json()) as { webSocketDebuggerUrl: string };
  const wsEndpoint = versionInfo.webSocketDebuggerUrl;

  console.log(`CDP WebSocket endpoint: ${wsEndpoint}`);

  const pageRegistry = new Map<string, { page: Page; targetId: string }>();

  async function getTargetId(page: Page): Promise<string> {
    const session = await context.newCDPSession(page);
    const { targetInfo } = await session.send("Target.getTargetInfo");
    await session.detach();
    return targetInfo.targetId;
  }

  const app = express();
  app.use(express.json());

  app.get("/", (_req, res) => {
    const info: ServerInfoResponse = { wsEndpoint };
    res.json(info);
  });

  app.get("/pages", (_req, res) => {
    const response: ListPagesResponse = {
      pages: Array.from(pageRegistry.keys()),
    };
    res.json(response);
  });

  app.post("/pages", async (req, res) => {
    const { name } = req.body as { name: string };

    if (!name) {
      res.status(400).json({ error: "name is required" });
      return;
    }

    let entry = pageRegistry.get(name);

    if (!entry) {
      const page = await context.newPage();
      const targetId = await getTargetId(page);

      entry = { page, targetId };
      pageRegistry.set(name, entry);

      page.on("close", () => {
        pageRegistry.delete(name);
      });

      console.log(`Created page "${name}" with targetId: ${targetId}`);
    }

    const response: GetPageResponse = {
      wsEndpoint,
      name,
      targetId: entry.targetId,
    };
    res.json(response);
  });

  app.delete("/pages/:name", async (req, res) => {
    const { name } = req.params;
    const entry = pageRegistry.get(name);

    if (!entry) {
      res.status(404).json({ error: "Page not found" });
      return;
    }

    await entry.page.close();
    pageRegistry.delete(name);
    res.json({ success: true });
  });

  const server = app.listen(port, () => {
    console.log(`Server listening on http://localhost:${port}`);
  });

  const stop = async () => {
    console.log("Shutting down...");
    server.close();
    await context.close();
  };

  process.on("SIGINT", stop);
  process.on("SIGTERM", stop);

  return {
    wsEndpoint,
    port,
    stop,
  };
}

import {
  chromium,
  type Browser,
  type Page,
  type ElementHandle,
} from "playwright";
import type {
  GetPageResponse,
  ListPagesResponse,
  ServerInfoResponse,
} from "./types.js";
import { takeSnapshot, selectRef } from "./snapshot/index.js";
import {
  setupConsoleCapture,
  setupNetworkCapture,
  getConsoleMessages,
  getNetworkRequests,
  getPerformanceMetrics,
  getCoreWebVitals,
  startPerformanceTrace,
  stopPerformanceTrace,
} from "./devtools.js";

export interface DevBrowserClient {
  page: (name: string) => Promise<Page>;
  getAISnapshot: (pageName: string) => Promise<string>;
  selectSnapshotRef: (pageName: string, ref: string) => Promise<ElementHandle | null>;
  listPages: () => Promise<string[]>;
  closePage: (name: string) => Promise<void>;
  disconnect: () => Promise<void>;

  getConsoleMessages: typeof getConsoleMessages;
  getNetworkRequests: typeof getNetworkRequests;
  getPerformanceMetrics: typeof getPerformanceMetrics;
  getCoreWebVitals: typeof getCoreWebVitals;
  startPerformanceTrace: typeof startPerformanceTrace;
  stopPerformanceTrace: typeof stopPerformanceTrace;
}

let browser: Browser | null = null;
let connectingPromise: Promise<Browser> | null = null;

const pageCache = new Map<string, { page: Page; targetId: string }>();

async function ensureConnected(serverUrl: string): Promise<Browser> {
  if (browser?.isConnected()) {
    return browser;
  }

  if (connectingPromise) {
    return connectingPromise;
  }

  connectingPromise = (async () => {
    const infoResponse = await fetch(serverUrl);
    const info = (await infoResponse.json()) as ServerInfoResponse;

    browser = await chromium.connectOverCDP(info.wsEndpoint);
    return browser;
  })();

  try {
    return await connectingPromise;
  } finally {
    connectingPromise = null;
  }
}

async function findPageByTargetId(
  browser: Browser,
  targetId: string
): Promise<Page | null> {
  for (const context of browser.contexts()) {
    for (const page of context.pages()) {
      try {
        const session = await context.newCDPSession(page);
        const { targetInfo } = await session.send("Target.getTargetInfo");
        await session.detach();

        if (targetInfo.targetId === targetId) {
          return page;
        }
      } catch {
        continue;
      }
    }
  }
  return null;
}

export async function connect(serverUrl: string = "http://localhost:9222"): Promise<DevBrowserClient> {
  const connectedBrowser = await ensureConnected(serverUrl);

  async function getPage(name: string): Promise<Page> {
    const cached = pageCache.get(name);
    if (cached) {
      try {
        await cached.page.evaluate(() => true);
        return cached.page;
      } catch {
        pageCache.delete(name);
      }
    }

    const response = await fetch(`${serverUrl}/pages`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ name }),
    });

    const pageInfo = (await response.json()) as GetPageResponse;

    let page = await findPageByTargetId(connectedBrowser, pageInfo.targetId);

    if (!page) {
      await ensureConnected(serverUrl);
      page = await findPageByTargetId(connectedBrowser, pageInfo.targetId);
    }

    if (!page) {
      throw new Error(`Could not find page with targetId: ${pageInfo.targetId}`);
    }

    await setupConsoleCapture(page);
    await setupNetworkCapture(page);

    pageCache.set(name, { page, targetId: pageInfo.targetId });
    return page;
  }

  async function getAISnapshot(pageName: string): Promise<string> {
    const page = await getPage(pageName);
    return takeSnapshot(page);
  }

  async function selectSnapshotRef(
    pageName: string,
    ref: string
  ): Promise<ElementHandle | null> {
    const page = await getPage(pageName);
    return selectRef(page, ref);
  }

  async function listPages(): Promise<string[]> {
    const response = await fetch(`${serverUrl}/pages`);
    const data = (await response.json()) as ListPagesResponse;
    return data.pages;
  }

  async function closePage(name: string): Promise<void> {
    await fetch(`${serverUrl}/pages/${name}`, { method: "DELETE" });
    pageCache.delete(name);
  }

  async function disconnect(): Promise<void> {
    pageCache.clear();
    if (browser) {
      await browser.close();
      browser = null;
    }
  }

  return {
    page: getPage,
    getAISnapshot,
    selectSnapshotRef,
    listPages,
    closePage,
    disconnect,

    getConsoleMessages,
    getNetworkRequests,
    getPerformanceMetrics,
    getCoreWebVitals,
    startPerformanceTrace,
    stopPerformanceTrace,
  };
}

export interface WaitForPageLoadOptions {
  timeout?: number;
  pollInterval?: number;
  minimumWait?: number;
  waitForNetworkIdle?: boolean;
}

export interface WaitForPageLoadResult {
  success: boolean;
  readyState: string;
  pendingRequests: number;
  waitTimeMs: number;
  timedOut: boolean;
}

async function getPageLoadState(page: Page): Promise<{
  documentReady: boolean;
  pendingRequests: number;
  readyState: string;
}> {
  return page.evaluate(() => {
    const readyState = document.readyState;
    const documentReady = readyState === "complete";

    const resources = performance.getEntriesByType("resource") as PerformanceResourceTiming[];
    const now = performance.now();

    const adPatterns = [
      "doubleclick", "googlesyndication", "googletagmanager", "google-analytics",
      "googleadservices", "facebook.net", "facebook.com/tr", "analytics.",
      "tracking.", "tracker.", "adservice.", "hotjar", "mixpanel", "segment",
      "amplitude", "fullstory", "clarity.ms", "newrelic", "sentry", "bugsnag",
      "/beacon", "/pixel", "/tracker", "/telemetry", "/metrics", "/collect"
    ];

    const nonCriticalTypes = ["img", "image", "icon", "font"];
    const imageExts = [".jpg", ".jpeg", ".png", ".gif", ".webp", ".svg", ".ico"];

    const pendingResources = resources.filter((r) => {
      if (r.responseEnd > 0) return false;

      const url = r.name.toLowerCase();
      const loadingTime = now - r.startTime;

      if (url.startsWith("data:")) return false;
      if (url.length > 500) return false;
      if (loadingTime > 10000) return false;
      if (adPatterns.some((p) => url.includes(p))) return false;

      const isNonCritical =
        nonCriticalTypes.includes(r.initiatorType.toLowerCase()) ||
        imageExts.some((ext) => url.includes(ext));

      if (isNonCritical && loadingTime > 3000) return false;

      return true;
    });

    return {
      documentReady,
      pendingRequests: pendingResources.length,
      readyState,
    };
  });
}

export async function waitForPageLoad(
  page: Page,
  options: WaitForPageLoadOptions = {}
): Promise<WaitForPageLoadResult> {
  const {
    timeout = 10000,
    pollInterval = 50,
    minimumWait = 100,
    waitForNetworkIdle = true,
  } = options;

  const startTime = Date.now();

  if (minimumWait > 0) {
    await page.waitForTimeout(minimumWait);
  }

  let lastState = { documentReady: false, pendingRequests: 0, readyState: "loading" };

  while (Date.now() - startTime < timeout) {
    lastState = await getPageLoadState(page);

    const networkIdle = !waitForNetworkIdle || lastState.pendingRequests === 0;

    if (lastState.documentReady && networkIdle) {
      return {
        success: true,
        readyState: lastState.readyState,
        pendingRequests: lastState.pendingRequests,
        waitTimeMs: Date.now() - startTime,
        timedOut: false,
      };
    }

    await page.waitForTimeout(pollInterval);
  }

  return {
    success: lastState.documentReady && lastState.pendingRequests === 0,
    readyState: lastState.readyState,
    pendingRequests: lastState.pendingRequests,
    waitTimeMs: Date.now() - startTime,
    timedOut: true,
  };
}

