import type { Page } from "playwright";
import { readFileSync } from "fs";
import { fileURLToPath } from "url";
import { dirname, join } from "path";

const __filename = fileURLToPath(import.meta.url);
const __dirname = dirname(__filename);

let browserScriptSource: string | null = null;

function getBrowserScript(): string {
  if (browserScriptSource) return browserScriptSource;

  const scriptPath = join(__dirname, "browser-script.ts");
  const tsSource = readFileSync(scriptPath, "utf-8");

  const jsSource = tsSource
    .replace(/export\s+/g, "")
    .replace(/declare\s+global\s*\{[\s\S]*?\}\s*/g, "")
    .replace(/interface\s+\w+\s*\{[\s\S]*?\}/g, "")
    .replace(/<[^>]+>/g, "")
    .replace(/:\s*\w+(\[\])?(\s*\|\s*\w+(\[\])?)*\s*(?=[=;,)\]}])/g, "")
    .replace(/:\s*\w+(\[\])?(\s*\|\s*\w+(\[\])?)*\s*(?=\s*\{)/g, "")
    .replace(/as\s+\w+(\[\])?/g, "")
    .replace(/`/g, "\\`")
    .replace(/\$\{/g, "\\${");

  browserScriptSource = jsSource;
  return browserScriptSource;
}

export async function takeSnapshot(page: Page): Promise<string> {
  const script = getBrowserScript();

  const snapshot = await page.evaluate(`
    (function() {
      ${script}
      return getAISnapshot();
    })()
  `);

  return snapshot as string;
}

export async function selectRef(
  page: Page,
  ref: string
): Promise<ReturnType<Page["$"]>> {
  const elementHandle = await page.evaluateHandle((refId: string) => {
    return window.__devBrowserRefs?.[refId] || null;
  }, ref);

  const element = elementHandle.asElement();
  return element;
}
